import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForRad1,validRad1,advanceRad1,numericRad1,experimentOptions,experimentResult,experimentCases,experimentValid,predictionValid,outputLabel}from './rad1-models.js?v=20261023-physicscomplete01';import{showRad1}from './rad1-visuals.js?v=20261023-physicscomplete01';export{showRad1};
export function mountRad1(l,p,root,{save,done,feedback}){let ts=tasksForRad1(l.widget.slice(5),l.learnerTier),w=p.widget;w.rad1Task??=ts[0].id;w.rad1Drafts??={};w.rad1Passed??=[];let i=ts.findIndex(t=>t.id===w.rad1Task);if(i<0)i=0;let t=ts[i],v=w.rad1Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountRad1(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.rad1Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('rad1Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('rad1Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealRad1">Reveal evidence →</button><p id="rad1Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showRad1(t.kind,{state:c[0],context:'comparison',title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#rad1Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validRad1(c,v.answer);}
else if(t.type==='sequence'){body=field('rad1Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceRad1">Advance pathway →</button><p id="rad1Readout" aria-live="polite"></p>';draw=()=>{showRad1(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#rad1Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('rad1A',o.labels[0],o.a,v.a)+field('rad1B',o.labels[1],o.b,v.b)+(o.choices?field('rad1Prediction','Predict / '+o.unit,o.choices,v.prediction):'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="rad1Prediction" value="'+(v.prediction??'')+'"></label>')+'<button class="secondary" id="rad1Run">Reveal model output →</button><p id="rad1Output"></p>'+field('rad1Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showRad1(t.kind,{a:v.a,b:v.b,wiring:v.wiring,revealed:v.ran,title:t.title});$('#rad1Output').textContent=v.ran?'Model output: '+outputLabel(t.experiment,r.value):'Predict first. Use the selected quantities and the relationship explained in Discover.';};valid=()=>!!v.ran&&predictionValid(t.experiment,v.prediction,experimentResult(t.experiment,v.a,v.b));}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="rad1Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="rad1Number" type="number" step="any" value="'+(v.number??'')+'">'+field('rad1Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showRad1(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericRad1(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="rad1Evidence"></p><div class="lab-actions"><button class="secondary" id="recordRad1">Record reasoning</button><button class="secondary" id="nextRad1">Next challenge →</button></div><p id="rad1Progress"></p>';
const status=()=>{$('#rad1Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.rad1Passed.includes(t.id)?'Challenge recorded.':'';$('#rad1Progress').textContent=ts.filter(t=>w.rad1Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='rad1A'||id==='rad1B'){if(!val){remount();return;}v[id==='rad1A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='rad1Interpretation'){v.interpretation=val;save();return;}if(id==='rad1Prediction'){v.prediction=val;save();return;}if(id==='rad1Case'){if(val===''){remount();return;}v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='rad1Answer')v.answer=val;else if(id==='rad1Next')v.next=val;else if(id==='rad1Number')v.number=val;else if(id==='rad1Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='rad1Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#rad1Run'))$('#rad1Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Make a prediction first.',true);return;}v.ran=true;save();draw();};
if($('#revealRad1'))$('#revealRad1').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validRad1(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validRad1(t.cases[v.case],v.answer));};
if($('#advanceRad1'))$('#advanceRad1').onclick=()=>{let n=advanceRad1(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordRad1').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.rad1Passed.includes(t.id))w.rad1Passed.push(t.id);p.widgetDone=ts.every(t=>w.rad1Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextRad1').onclick=()=>{if(!w.rad1Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.rad1Task=ts[(i+1)%ts.length].id;save();remount();};}
